/**
 * Isolated preview of ONE chapter, with the global background and overlays shifted to
 * the chapter's place in the film, so it looks exactly like it will in "Long".
 * Imports only that chapter's component (never registry.ts), so other chapters'
 * broken files cannot break it. Entry files are generated by scripts/long-preview.sh:
 *
 *   registerRoot(makeChapterRoot("C05", C05));   // composition id "C05"
 *   registerRoot(makeChapterRoot("C05"));        // no component yet -> placeholder
 *
 * Duration = the chapter's full length (including its transition overlaps).
 */
import React from "react";
import { AbsoluteFill, Audio, Composition, Sequence, staticFile } from "remotion";
import { Grain } from "../../overlays/Grain";
import { FPS, HEIGHT, WIDTH } from "../../theme/layout";
import { ChapterId, LONG_START, LONG_TOTAL, chapterFrames, chapterSpec } from "../chapters";
import { BackgroundLong } from "../overlays/BackgroundLong";
import { LongOverlays } from "../overlays/LongOverlays";
import { placeholderFor } from "../Placeholder";
import { VO_TIMING } from "../data/voTiming";

// The chapter's own voice clip, so previews can be watched with sound.
const Voice: React.FC<{ id: ChapterId }> = ({ id }) => {
  const v = VO_TIMING[id];
  if (!v) return null;
  return (
    <Sequence from={Math.round(v.clipAt * FPS)} layout="none">
      <Audio src={staticFile(v.src)} />
    </Sequence>
  );
};

export const ChapterPreview: React.FC<{ id: ChapterId; Chapter: React.FC }> = ({ id, Chapter }) => {
  const start = LONG_START[id];
  return (
    <AbsoluteFill>
      <Sequence from={-start}>
        <BackgroundLong totalFrames={LONG_TOTAL} />
      </Sequence>
      <Chapter />
      <Sequence from={-start}>
        <LongOverlays />
      </Sequence>
      <Grain />
      <Voice id={id} />
    </AbsoluteFill>
  );
};

export const makeChapterRoot = (id: ChapterId, Chapter?: React.FC): React.FC => {
  chapterSpec(id); // throws a readable error for unknown ids
  const Body = Chapter ?? placeholderFor(id);
  const Comp: React.FC = () => <ChapterPreview id={id} Chapter={Body} />;
  return () => (
    <Composition id={id} component={Comp} durationInFrames={chapterFrames(id)} fps={FPS} width={WIDTH} height={HEIGHT} />
  );
};
